using Azure.Identity;
using Azure.AI.OpenAI;
using Microsoft.Extensions.AI;

var builder = WebApplication.CreateBuilder(args);

var endpoint = builder.Configuration["AzureOpenAI:Endpoint"]; // e.g. https://my-enterprise-ai.openai.azure.com/
var deployment = builder.Configuration["AzureOpenAI:DeploymentName"] ?? "gpt-4o";

// Register AzureOpenAIClient with Managed Identity (DefaultAzureCredential)
builder.Services.AddSingleton<AzureOpenAIClient>(sp =>
{
    return new AzureOpenAIClient(
        new Uri(endpoint!),
        new DefaultAzureCredential());
});

// Register unified IChatClient abstraction
builder.Services.AddChatClient(sp =>
{
    var client = sp.GetRequiredService<AzureOpenAIClient>();
    return client.GetChatClient(deployment).AsChatClient();
});
